function LoginScreen({ onEnter }: { onEnter: (role: Role) => void }) {
  const [role, setRole] = useState<Role>("management")
  return <main className="login-canvas min-h-svh p-4 md:p-7"><div className="mx-auto flex min-h-[calc(100svh-2rem)] max-w-[1500px] overflow-hidden rounded-[2rem] border bg-card shadow-[0_32px_100px_-42px_rgba(16,38,54,.45)] md:min-h-[calc(100svh-3.5rem)]">
    <section className="relative hidden w-[56%] overflow-hidden bg-primary p-12 text-primary-foreground lg:flex lg:flex-col"><div className="school-grid absolute inset-0 opacity-20"/><div className="relative z-10 flex items-center gap-3"><Logo/><Badge className="border-primary-foreground/20 bg-primary-foreground/10 text-primary-foreground">SRS v2</Badge></div><div className="relative z-10 my-auto max-w-2xl py-16"><p className="mb-5 flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.22em] text-primary-foreground/65"><Sparkles className="size-4"/> One connected campus</p><h1 className="font-heading text-5xl font-semibold leading-[1.05] tracking-[-0.045em] xl:text-7xl">Every school day,<br/><span className="text-accent">beautifully organised.</span></h1><p className="mt-7 max-w-xl text-lg leading-8 text-primary-foreground/70">A complete operating system for management, teachers and parents—from admissions to verified receipts and published report cards.</p></div><div className="relative z-10 grid grid-cols-3 gap-3">{[["1,248","active students"],["94.2%","attendance"],["24","connected modules"]].map(([value,label])=><div key={label} className="rounded-2xl border border-primary-foreground/15 bg-primary-foreground/[0.06] p-4 backdrop-blur"><p className="font-heading text-2xl font-semibold">{value}</p><p className="mt-1 text-xs text-primary-foreground/55">{label}</p></div>)}</div></section>
    <section className="flex flex-1 items-center justify-center p-6 sm:p-10 lg:p-14"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><Logo/></div><Badge variant="secondary" className="mb-4">Portal access</Badge><h2 className="font-heading text-3xl font-semibold tracking-tight md:text-4xl">Welcome back</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Choose a portal to explore the complete interactive prototype.</p><div className="mt-7 grid gap-2">{(Object.keys(roles) as Role[]).map((roleKey)=>{const item=roles[roleKey];const Icon=item.icon;return <button key={roleKey} onClick={()=>setRole(roleKey)} className={`group flex items-center gap-4 rounded-2xl border p-4 text-left transition-all ${role===roleKey?'border-primary bg-primary/[0.04] shadow-sm ring-2 ring-primary/10':'hover:border-primary/25 hover:bg-muted/50'}`}><span className={`grid size-11 place-items-center rounded-xl ${role===roleKey?'bg-primary text-primary-foreground':'bg-muted text-muted-foreground'}`}><Icon className="size-5"/></span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold">{item.label}</span><span className="mt-0.5 block truncate text-xs text-muted-foreground">{item.description}</span></span><span className={`grid size-5 place-items-center rounded-full border ${role===roleKey?'border-primary bg-primary text-primary-foreground':'border-border'}`}>{role===roleKey&&<Check className="size-3"/>}</span></button>})}</div><div className="mt-6 grid gap-2"><label className="text-xs font-medium" htmlFor="portal-email">Email or user ID</label><Input id="portal-email" key={role} defaultValue={role==='parent'?'parent@cls.edu.pk':role==='teacher'?'hassan@cls.edu.pk':'admin@cls.edu.pk'}/></div><div className="mt-4 grid gap-2"><div className="flex items-center justify-between"><label className="text-xs font-medium" htmlFor="portal-password">Password</label><button className="text-xs font-medium text-primary">Forgot password?</button></div><Input id="portal-password" type="password" defaultValue="password"/></div><Button size="lg" className="mt-6 w-full" onClick={()=>onEnter(role)}>Explore {roles[role].short} portal <ArrowRight data-icon="inline-end"/></Button><p className="mt-5 text-center text-xs text-muted-foreground"><ShieldCheck className="mr-1 inline size-3.5"/>Role-based access · Audit protected · SRS v2 prototype</p></div></section>
  </div></main>
}

function SidebarNav({ role, active, onNavigate, onRole, onLogout }: { role: Role; active: string; onNavigate: (v: string) => void; onRole: (v: Role) => void; onLogout: () => void }) {
  return <div className="flex h-full flex-col p-3"><div className="px-2 py-3"><Logo/></div><div className="mt-5 px-2"><p className="text-[10px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">Workspace</p></div><nav className="mt-2 flex flex-1 flex-col gap-1">{navigation[role].map((item)=>{const Icon=item.icon;return <button key={item.label} onClick={()=>onNavigate(item.label)} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm transition-colors ${active===item.label?'bg-sidebar-primary text-sidebar-primary-foreground shadow-sm':'text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground'}`}><Icon className="size-4"/><span>{item.label}</span></button>})}</nav><div className="rounded-2xl border bg-background/70 p-3"><div className="flex items-center gap-3"><Avatar className="size-9"><AvatarFallback>{roles[role].initials}</AvatarFallback></Avatar><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{roles[role].user}</p><p className="truncate text-[11px] text-muted-foreground">{roles[role].label}</p></div><Tooltip><TooltipTrigger asChild><Button variant="ghost" size="icon-sm" onClick={onLogout}><LogOut/></Button></TooltipTrigger><TooltipContent>Sign out</TooltipContent></Tooltip></div><Select value={role} onValueChange={(value)=>onRole(value as Role)}><SelectTrigger className="mt-3 h-8 w-full text-xs"><SelectValue/></SelectTrigger><SelectContent><SelectGroup>{(Object.keys(roles) as Role[]).map((r)=><SelectItem value={r} key={r}>{roles[r].short} demo</SelectItem>)}</SelectGroup></SelectContent></Select></div></div>
}

function PageHeader({ role, title, subtitle, onAction }: { role: Role; title: string; subtitle: string; onAction: (a: ActionKind) => void }) {
  const action=role==="management"?{label:"New admission",kind:"admission" as ActionKind,icon:Plus}:role==="teacher"?{label:"Mark attendance",kind:"attendance" as ActionKind,icon:UserCheck}:{label:"Download DMC",kind:null,icon:Download};const Icon=action.icon
  return <header className="flex flex-col gap-4 border-b bg-background/85 px-5 py-5 backdrop-blur-xl sm:flex-row sm:items-center sm:justify-between md:px-8"><div><div className="mb-1 flex items-center gap-2 text-xs text-muted-foreground"><span>2026–27</span><span>•</span><span>{roles[role].short}</span></div><h1 className="font-heading text-2xl font-semibold tracking-tight md:text-3xl">{title}</h1><p className="mt-1 text-sm text-muted-foreground">{subtitle}</p></div><div className="flex items-center gap-2"><div className="relative hidden lg:block"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input className="w-56 pl-9" placeholder="Search anything…"/></div><Button variant="outline" size="icon"><Bell/></Button><Button onClick={()=>action.kind?onAction(action.kind):toast.success("DMC download prepared")}><Icon data-icon="inline-start"/>{action.label}</Button></div></header>
}

function MetricCard({ icon: Icon, label, value, note, tone="default" }: { icon: Icon; label: string; value: string; note: string; tone?: "default"|"accent" }) {
  return <Card className={tone==="accent"?"overflow-hidden border-primary/10 bg-primary text-primary-foreground":"overflow-hidden"}><CardContent className="p-5"><div className="flex items-start justify-between"><div className={`grid size-10 place-items-center rounded-xl ${tone==='accent'?'bg-primary-foreground/10':'bg-muted'}`}><Icon className="size-5"/></div><Badge variant={tone==='accent'?'outline':'secondary'} className={tone==='accent'?'border-primary-foreground/20 text-primary-foreground':''}><TrendingUp className="size-3"/> live</Badge></div><p className={`mt-6 text-xs ${tone==='accent'?'text-primary-foreground/60':'text-muted-foreground'}`}>{label}</p><p className="mt-1 font-heading text-3xl font-semibold tracking-tight">{value}</p><p className={`mt-2 text-xs ${tone==='accent'?'text-primary-foreground/60':'text-muted-foreground'}`}>{note}</p></CardContent></Card>
}
function SectionHeading({ title, detail, action }: { title: string; detail: string; action?: string }) { return <div className="flex items-end justify-between gap-4"><div><h2 className="font-heading text-xl font-semibold tracking-tight">{title}</h2><p className="mt-1 text-sm text-muted-foreground">{detail}</p></div>{action&&<Button variant="ghost" size="sm">{action}<ArrowRight data-icon="inline-end"/></Button>}</div> }
function StatusBadge({ value }: { value: string }) { const good=["Active","Paid","Published","Present","Complete","Synced","Completed","Approved"].includes(value);return <Badge variant={good?"secondary":"outline"} className={good?"bg-success/10 text-success":""}>{value}</Badge> }

function ManagementDashboard({ onAction }: { onAction: (a: ActionKind) => void }) {
  return <div className="grid gap-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={Users} label="Active students" value="1,248" note="+32 this session" tone="accent"/><MetricCard icon={UserCheck} label="Today’s attendance" value="94.2%" note="1,176 present today"/><MetricCard icon={WalletCards} label="September collected" value="₨ 6.8m" note="83% of monthly target"/><MetricCard icon={FileCheck2} label="Open admissions" value="47" note="12 require review"/></div><div className="grid gap-4 xl:grid-cols-[1.5fr_1fr]"><Card><CardHeader className="flex-row items-start justify-between"><div><CardTitle>Enrollment growth</CardTitle><CardDescription>Current session student strength</CardDescription></div><Badge variant="outline">Live register</Badge></CardHeader><CardContent><ChartContainer config={chartConfig} className="h-[245px] w-full"><AreaChart data={enrollmentData} margin={{left:0,right:8,top:10}}><defs><linearGradient id="fillStudents" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="var(--color-students)" stopOpacity={0.32}/><stop offset="95%" stopColor="var(--color-students)" stopOpacity={0.02}/></linearGradient></defs><CartesianGrid vertical={false}/><XAxis dataKey="month" tickLine={false} axisLine={false}/><ChartTooltip content={<ChartTooltipContent/>}/><Area dataKey="students" type="monotone" fill="url(#fillStudents)" stroke="var(--color-students)" strokeWidth={2.5}/></AreaChart></ChartContainer></CardContent></Card><Card><CardHeader><CardTitle>Attention queue</CardTitle><CardDescription>Items needing management action</CardDescription></CardHeader><CardContent className="grid gap-1">{[["12","Applications to review","Admissions"],["3","Timetable conflicts","Academic"],["2","Marks reopen requests","Exams"],["18","Overdue fee accounts","Fees"]].map(([n,title,tag])=><button key={title} className="flex items-center gap-3 rounded-xl p-3 text-left hover:bg-muted"><span className="grid size-9 place-items-center rounded-lg bg-muted text-sm font-semibold">{n}</span><span className="min-w-0 flex-1"><span className="block text-sm font-medium">{title}</span><span className="block text-xs text-muted-foreground">{tag}</span></span><ArrowRight className="size-4 text-muted-foreground"/></button>)}</CardContent></Card></div><Card><CardHeader className="flex-row items-center justify-between"><div><CardTitle>Recent fee activity</CardTitle><CardDescription>Online and synchronised offline payments</CardDescription></div><div className="flex gap-2"><Button variant="outline" size="sm" onClick={()=>onAction("sync")}><CloudUpload data-icon="inline-start"/>Offline sync</Button><Button size="sm" onClick={()=>onAction("payment")}><Plus data-icon="inline-start"/>Record payment</Button></div></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Receipt</TableHead><TableHead>Student</TableHead><TableHead>Fee</TableHead><TableHead>Amount</TableHead><TableHead>Status</TableHead><TableHead/></TableRow></TableHeader><TableBody>{transactions.map(row=><TableRow key={row.ref}><TableCell className="font-mono text-xs">{row.ref}</TableCell><TableCell className="font-medium">{row.student}</TableCell><TableCell>{row.type}</TableCell><TableCell>{row.amount}</TableCell><TableCell><StatusBadge value={row.status}/></TableCell><TableCell><Button variant="ghost" size="icon-sm"><MoreHorizontal/></Button></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></div>
}

function AcademicSetup() {
  return <div className="grid gap-6"><SectionHeading title="Academic foundation" detail="The controlled structure behind every enrollment, class and report." action="Session settings"/><div className="grid gap-4 lg:grid-cols-3">{[[CalendarDays,"Academic session","2026–27 is current","01 Apr 2026 — 31 Mar 2027","1 current · 3 archived"],[LibraryBig,"Classes & sections","Grades Playgroup–10","28 sections across 13 grades","1,248 enrolled students"],[BookOpen,"Subjects & allocation","64 subject records","48 teachers assigned","No duplicate class subjects"]].map(([I,title,big,detail,foot])=>{const X=I as Icon;return <Card key={String(title)}><CardHeader><div className="grid size-10 place-items-center rounded-xl bg-muted"><X className="size-5"/></div><CardTitle className="mt-5">{title as string}</CardTitle><CardDescription>{detail as string}</CardDescription></CardHeader><CardContent><p className="font-heading text-2xl font-semibold">{big as string}</p></CardContent><CardFooter className="justify-between border-t pt-4 text-xs text-muted-foreground"><span>{foot as string}</span><ArrowRight className="size-4"/></CardFooter></Card>})}</div><div className="grid gap-4 xl:grid-cols-[1.3fr_1fr]"><Card><CardHeader><CardTitle>Weekly timetable</CardTitle><CardDescription>Grade 7 · Blue — conflict-aware scheduling</CardDescription></CardHeader><CardContent className="overflow-x-auto"><div className="grid min-w-[620px] grid-cols-[70px_repeat(5,1fr)] gap-2 text-xs"><div/>{["Mon","Tue","Wed","Thu","Fri"].map(d=><div key={d} className="pb-2 text-center font-semibold">{d}</div>)}{["08:00","08:45","09:30"].flatMap((time,row)=>[<div key={time} className="pt-3 text-muted-foreground">{time}</div>,...["Mathematics","English","Science","Computer","Urdu"].map((subject,col)=><div key={`${row}-${col}`} className="rounded-xl border bg-muted/40 p-3"><p className="font-medium">{[subject,"Science","English"][(col+row)%3]}</p><p className="mt-1 text-muted-foreground">{["H. Ali","S. Noor","M. Khan"][(row+col)%3]} · R{12+col}</p></div>)])}</div></CardContent></Card><Card><CardHeader><CardTitle>Scheduling health</CardTitle><CardDescription>Automatic conflict checks</CardDescription></CardHeader><CardContent className="grid gap-4"><Alert><ShieldCheck className="size-4"/><AlertTitle>No blocking conflicts</AlertTitle><AlertDescription>Teacher, room and class overlaps are currently clear.</AlertDescription></Alert>{[["Teacher allocation","48 of 52","92"],["Room allocation","26 of 28","93"],["Timetable coverage","184 of 190","97"]].map(([label,value,p])=><div key={label}><div className="mb-2 flex justify-between text-xs"><span>{label}</span><span className="text-muted-foreground">{value}</span></div><Progress value={Number(p)}/></div>)}</CardContent></Card></div></div>
}

function Admissions({ onAction }: { onAction: (a: ActionKind) => void }) { return <div className="grid gap-6"><SectionHeading title="Admissions & student records" detail="From initial application to active session enrollment."/><div className="grid gap-4 sm:grid-cols-3"><MetricCard icon={FileCheck2} label="New applications" value="47" note="September intake"/><MetricCard icon={Clock3} label="Awaiting review" value="12" note="Oldest: 2 days"/><MetricCard icon={BadgeCheck} label="Enrolled this month" value="28" note="All documents verified"/></div><Card><CardHeader className="flex-row items-center justify-between"><div><CardTitle>Student register</CardTitle><CardDescription>Current-session identity, guardian and class records</CardDescription></div><Button onClick={()=>onAction("admission")}><Plus data-icon="inline-start"/>New admission</Button></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Student ID</TableHead><TableHead>Name</TableHead><TableHead>Class</TableHead><TableHead>Guardian</TableHead><TableHead>Status</TableHead><TableHead/></TableRow></TableHeader><TableBody>{students.map(s=><TableRow key={s.id}><TableCell className="font-mono text-xs">{s.id}</TableCell><TableCell className="font-medium">{s.name}</TableCell><TableCell>{s.className}</TableCell><TableCell>{s.guardian}</TableCell><TableCell><StatusBadge value={s.status}/></TableCell><TableCell><Button variant="ghost" size="icon-sm"><MoreHorizontal/></Button></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></div> }

function Examinations({ onAction }: { onAction: (a: ActionKind) => void }) { return <div className="grid gap-6"><SectionHeading title="Examinations & results" detail="Controlled marks, grading, ranks, publishing and printable DMCs." action="Grade rules"/><div className="grid gap-4 lg:grid-cols-3">{[["Active exams","3","Across 18 class sections"],["Marks completed","82%","422 of 514 subject sheets"],["Ready to publish","6","Class result sets verified"]].map(([l,v,n])=><Card key={l}><CardContent className="p-5"><p className="text-xs text-muted-foreground">{l}</p><p className="mt-2 font-heading text-3xl font-semibold">{v}</p><p className="mt-2 text-xs text-muted-foreground">{n}</p></CardContent></Card>)}</div><Card><CardHeader className="flex-row items-center justify-between"><div><CardTitle>Exam control room</CardTitle><CardDescription>Draft → submitted → verified → published</CardDescription></div><Button variant="outline" onClick={()=>onAction("marks")}><FileCheck2 data-icon="inline-start"/>Review marks</Button></CardHeader><CardContent className="grid gap-3">{examRows.map(row=><div key={row.exam+row.className} className="grid gap-4 rounded-2xl border p-4 md:grid-cols-[1.4fr_1fr_1fr_1.5fr_auto] md:items-center"><div><p className="text-sm font-semibold">{row.exam}</p><p className="text-xs text-muted-foreground">{row.className}</p></div><div><p className="text-[11px] text-muted-foreground">Subjects</p><p className="text-sm font-medium">{row.subjects}</p></div><div><p className="text-[11px] text-muted-foreground">Progress</p><p className="text-sm font-medium">{row.progress}%</p></div><Progress value={row.progress}/><StatusBadge value={row.status}/></div>)}</CardContent></Card></div> }

function Fees({ onAction }: { onAction: (a: ActionKind) => void }) {
  return <div className="grid gap-6"><SectionHeading title="Fees & offline synchronisation" detail="Validated collection, outstanding balances, advances and duplicate-safe Excel import."/><div className="grid gap-4 xl:grid-cols-[1.3fr_1fr]"><Card><CardHeader><CardTitle>Collection against target</CardTitle><CardDescription>Monthly performance in PKR millions</CardDescription></CardHeader><CardContent><ChartContainer config={chartConfig} className="h-[260px] w-full"><BarChart data={feeData}><CartesianGrid vertical={false}/><XAxis dataKey="month" tickLine={false} axisLine={false}/><ChartTooltip content={<ChartTooltipContent/>}/><Bar dataKey="collection" fill="var(--color-collection)" radius={[6,6,0,0]}/><Bar dataKey="target" fill="var(--color-target)" opacity={0.22} radius={[6,6,0,0]}/></BarChart></ChartContainer></CardContent></Card><Card className="border-accent/25 bg-accent/[0.06]"><CardHeader><div className="flex items-center justify-between"><div className="grid size-11 place-items-center rounded-xl bg-accent text-accent-foreground"><FileSpreadsheet className="size-5"/></div><Badge variant="secondary">Controlled import</Badge></div><CardTitle className="mt-5">Offline fee desk</CardTitle><CardDescription>Keep collecting when connectivity is unreliable, then safely synchronise later.</CardDescription></CardHeader><CardContent className="grid gap-3">{["Download locked Excel template","Validate student, month and amount","Block duplicate receipt references","Import valid rows; report every error"].map((t,i)=><div key={t} className="flex items-center gap-3 text-sm"><span className="grid size-6 place-items-center rounded-full bg-background text-xs font-semibold">{i+1}</span>{t}</div>)}</CardContent><CardFooter className="gap-2"><Button variant="outline" className="flex-1" onClick={()=>toast.success("Fee template downloaded")}><Download data-icon="inline-start"/>Template</Button><Button className="flex-1" onClick={()=>onAction("sync")}><CloudUpload data-icon="inline-start"/>Upload</Button></CardFooter></Card></div><Card><CardHeader><CardTitle>Recent payments</CardTitle><CardDescription>Unique references protect the ledger from duplicates</CardDescription></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Reference</TableHead><TableHead>Student</TableHead><TableHead>Period</TableHead><TableHead>Amount</TableHead><TableHead>Status</TableHead></TableRow></TableHeader><TableBody>{transactions.map(t=><TableRow key={t.ref}><TableCell className="font-mono text-xs">{t.ref}</TableCell><TableCell>{t.student}</TableCell><TableCell>{t.type}</TableCell><TableCell>{t.amount}</TableCell><TableCell><StatusBadge value={t.status}/></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></div>
}

function Finance() {
  return <div className="grid gap-6"><SectionHeading title="Finance overview" detail="Income, expenses, cash movement and school-level operating position." action="Export statement"/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={TrendingUp} label="Income this month" value="₨ 7.42m" note="Fees + other income" tone="accent"/><MetricCard icon={CreditCard} label="Expenses" value="₨ 4.18m" note="62 posted entries"/><MetricCard icon={WalletCards} label="Net position" value="₨ 3.24m" note="43.6% operating margin"/><MetricCard icon={BriefcaseBusiness} label="Advances held" value="₨ 684k" note="Not counted as applied fees"/></div><div className="grid gap-4 xl:grid-cols-[1.2fr_1fr]"><Card><CardHeader><CardTitle>Expense categories</CardTitle><CardDescription>September 2026</CardDescription></CardHeader><CardContent className="grid gap-3">{[["Payroll","₨ 2.60m",62],["Facilities","₨ 684k",16],["Academic supplies","₨ 412k",10],["Transport","₨ 296k",7],["Other","₨ 188k",5]].map(([l,v,p])=><div key={l as string}><div className="mb-2 flex justify-between text-sm"><span>{l}</span><span className="font-medium">{v}</span></div><Progress value={p as number}/></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Recent ledger entries</CardTitle><CardDescription>Audited financial activity</CardDescription></CardHeader><CardContent className="grid gap-2">{[["Electricity bill","Facilities","− ₨ 184,500"],["Tuition batch","Fees","+ ₨ 642,000"],["Lab equipment","Academic","− ₨ 96,300"],["Transport fee batch","Fees","+ ₨ 214,000"]].map(([title,tag,value])=><div key={title} className="flex items-center gap-3 rounded-xl border p-3"><span className="grid size-9 place-items-center rounded-lg bg-muted"><ReceiptText className="size-4"/></span><span className="flex-1"><span className="block text-sm font-medium">{title}</span><span className="text-xs text-muted-foreground">{tag}</span></span><span className="text-sm font-semibold">{value}</span></div>)}</CardContent></Card></div></div>
}

function Reports() {
  return <div className="grid gap-6"><SectionHeading title="Reports & audit" detail="Printable insight with a traceable history of sensitive actions."/><Tabs defaultValue="reports"><TabsList><TabsTrigger value="reports">Report library</TabsTrigger><TabsTrigger value="audit">Audit trail</TabsTrigger></TabsList><TabsContent value="reports" className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{[[Users,"Enrollment register","Class, section and session strength"],[UserCheck,"Attendance summary","Daily, monthly and student analysis"],[WalletCards,"Fee outstanding","Paid, due, advance and aging"],[FileCheck2,"Exam analytics","Subject performance and ranks"],[Landmark,"Income & expense","Period-wise financial statement"],[FileSpreadsheet,"Offline sync log","Imported, skipped and failed rows"]].map(([I,t,d])=>{const X=I as Icon;return <Card key={t as string} className="group cursor-pointer transition hover:-translate-y-0.5 hover:shadow-md"><CardHeader><div className="flex items-center justify-between"><span className="grid size-10 place-items-center rounded-xl bg-muted"><X className="size-5"/></span><Download className="size-4 text-muted-foreground group-hover:text-foreground"/></div><CardTitle className="mt-5">{t as string}</CardTitle><CardDescription>{d as string}</CardDescription></CardHeader></Card>})}</TabsContent><TabsContent value="audit" className="mt-5"><Card><CardHeader><CardTitle>Security audit trail</CardTitle><CardDescription>Who changed what, when and from which role</CardDescription></CardHeader><CardContent className="grid gap-1">{[["Ayesha Khan","Published Grade 8 Monthly Assessment","2 min ago"],["Hassan Ali","Submitted Grade 7 Mathematics marks","18 min ago"],["Nadia — Fee Desk","Imported 84 offline fee rows","42 min ago"],["System","Blocked duplicate receipt RCPT-0926-417","43 min ago"]].map(([u,a,t])=><div key={a} className="flex items-center gap-3 border-b py-3 last:border-0"><Avatar className="size-8"><AvatarFallback>{u.slice(0,2).toUpperCase()}</AvatarFallback></Avatar><div className="flex-1"><p className="text-sm"><span className="font-semibold">{u}</span> {a}</p><p className="text-xs text-muted-foreground">{t}</p></div><Badge variant="outline">Recorded</Badge></div>)}</CardContent></Card></TabsContent></Tabs></div>
}

function DeliveryMap() {
  return <div className="grid gap-6"><div className="max-w-3xl"><Badge variant="secondary">SRS v2 coverage</Badge><h2 className="mt-4 font-heading text-3xl font-semibold tracking-tight">One product, delivered in three confident phases.</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">Every functional area in the updated specification is represented in this prototype, with permissions and data visibility changing by role.</p></div><div className="grid gap-4 lg:grid-cols-3">{phaseModules.map((p,i)=><Card key={p.phase} className={i===0?"border-primary/20":""}><CardHeader><div className="flex items-center justify-between"><Badge variant={i===0?"default":"secondary"}>{p.phase}</Badge><span className="text-xs text-muted-foreground">{p.status}</span></div><CardTitle className="mt-5 text-xl">{p.title}</CardTitle><CardDescription className="leading-6">{p.detail}</CardDescription></CardHeader><CardContent><Progress value={100}/><div className="mt-3 flex items-center gap-2 text-xs font-medium text-success"><BadgeCheck className="size-4"/>Represented in prototype</div></CardContent></Card>)}</div><Card><CardHeader><CardTitle>Cross-cutting controls</CardTitle><CardDescription>Rules that keep the complete system trustworthy</CardDescription></CardHeader><CardContent className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{[[ShieldCheck,"Role permissions","Only assigned or linked records are visible"],[FileCheck2,"Controlled approvals","Submitted marks require a reopen process"],[ReceiptText,"Ledger integrity","Positive payments and duplicate-safe references"],[Activity,"Live calculation","Dashboard and finance totals are derived from records"]].map(([I,t,d])=>{const X=I as Icon;return <div key={t as string} className="rounded-2xl bg-muted/50 p-4"><X className="size-5 text-primary"/><p className="mt-4 text-sm font-semibold">{t as string}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{d as string}</p></div>})}</CardContent></Card></div>
}

function TeacherPortal({ section, onAction }: { section: string; onAction: (a: ActionKind) => void }) {
  if(section==="Attendance")return <AttendanceWorkspace onAction={onAction}/>;if(section==="Marks entry")return <MarksWorkspace onAction={onAction}/>;if(section==="My classes")return <ClassesWorkspace/>;if(section==="Lesson progress")return <LessonWorkspace/>;if(section==="Daily updates")return <UpdatesWorkspace/>;
  return <div className="grid gap-6"><div className="teacher-hero relative overflow-hidden rounded-3xl bg-primary p-7 text-primary-foreground md:p-9"><div className="school-grid absolute inset-0 opacity-10"/><div className="relative z-10 max-w-xl"><p className="text-xs font-semibold uppercase tracking-[0.2em] text-primary-foreground/55">Monday · 21 September</p><h2 className="mt-4 font-heading text-3xl font-semibold tracking-tight md:text-4xl">Good morning, Hassan.</h2><p className="mt-3 text-sm leading-6 text-primary-foreground/65">You have 4 classes today. Grade 7 Mathematics attendance is ready to mark.</p><Button variant="secondary" className="mt-6" onClick={()=>onAction("attendance")}><UserCheck data-icon="inline-start"/>Start attendance</Button></div><div className="relative z-10 mt-8 grid max-w-2xl grid-cols-3 gap-3">{[["04","classes today"],["128","students"],["02","updates due"]].map(([v,l])=><div key={l} className="rounded-2xl border border-primary-foreground/10 bg-primary-foreground/[0.06] p-3"><p className="font-heading text-2xl font-semibold">{v}</p><p className="text-[11px] text-primary-foreground/55">{l}</p></div>)}</div></div><div className="grid gap-4 xl:grid-cols-[1.3fr_1fr]"><Card><CardHeader><CardTitle>Today’s timetable</CardTitle><CardDescription>Your assigned classes only</CardDescription></CardHeader><CardContent className="grid gap-2">{[["08:00","Grade 7 · Blue","Mathematics","Room 14","Complete"],["09:30","Grade 8 · Blue","Mathematics","Room 18","Next"],["11:15","Grade 7 · Green","Mathematics","Room 11","Upcoming"],["12:45","Grade 6 · Red","General Science","Lab 02","Upcoming"]].map(([time,cls,subject,room,status])=><div key={time} className="flex items-center gap-4 rounded-xl border p-3"><div className="w-12 text-center"><p className="text-xs font-semibold">{time}</p></div><Separator orientation="vertical" className="h-9"/><div className="flex-1"><p className="text-sm font-semibold">{cls}</p><p className="text-xs text-muted-foreground">{subject} · {room}</p></div><StatusBadge value={status}/></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Class pulse</CardTitle><CardDescription>Attendance this week</CardDescription></CardHeader><CardContent><ChartContainer config={attendanceConfig} className="h-[205px] w-full"><BarChart data={weeklyAttendance}><CartesianGrid vertical={false}/><XAxis dataKey="day" tickLine={false} axisLine={false}/><ChartTooltip content={<ChartTooltipContent/>}/><Bar dataKey="value" fill="var(--color-value)" radius={[7,7,0,0]}/></BarChart></ChartContainer><div className="mt-4 flex items-center justify-between rounded-xl bg-muted p-3"><span className="text-xs text-muted-foreground">Weekly average</span><span className="font-heading text-xl font-semibold">93.6%</span></div></CardContent></Card></div></div>
}

function ClassesWorkspace() { return <div className="grid gap-6"><SectionHeading title="My assigned classes" detail="Only the classes and subjects allocated to your profile."/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{[["Grade 7 · Blue","Mathematics","32 students",68],["Grade 8 · Blue","Mathematics","29 students",74],["Grade 7 · Green","Mathematics","34 students",61],["Grade 6 · Red","General Science","33 students",82]].map(([c,s,n,p])=><Card key={c as string}><CardHeader><div className="flex items-start justify-between"><span className="grid size-10 place-items-center rounded-xl bg-muted"><Users className="size-5"/></span><Badge variant="outline">2026–27</Badge></div><CardTitle className="mt-4">{c as string}</CardTitle><CardDescription>{s as string} · {n as string}</CardDescription></CardHeader><CardContent><div className="mb-2 flex justify-between text-xs"><span>Syllabus progress</span><span>{p}%</span></div><Progress value={p as number}/></CardContent><CardFooter className="border-t pt-4"><Button variant="ghost" className="w-full">Open class <ArrowRight data-icon="inline-end"/></Button></CardFooter></Card>)}</div></div> }
function AttendanceWorkspace({ onAction }: { onAction: (a: ActionKind) => void }) { return <div className="grid gap-6"><SectionHeading title="Attendance" detail="Mark and save attendance for your assigned class periods."/><div className="grid gap-4 sm:grid-cols-3"><MetricCard icon={UserCheck} label="Present today" value="118" note="92.9% across your classes"/><MetricCard icon={Users} label="Absent" value="6" note="3 require follow-up"/><MetricCard icon={Clock3} label="Not yet marked" value="1" note="Grade 8 · Blue"/></div><Card><CardHeader className="flex-row items-center justify-between"><div><CardTitle>Grade 8 · Blue</CardTitle><CardDescription>Mathematics · Period 2 · 29 students</CardDescription></div><Button onClick={()=>onAction("attendance")}><UserCheck data-icon="inline-start"/>Mark now</Button></CardHeader><CardContent><Alert><Clock3 className="size-4"/><AlertTitle>Attendance window is open</AlertTitle><AlertDescription>This class begins at 09:30. Save before the period ends at 10:15.</AlertDescription></Alert></CardContent></Card></div> }
function LessonWorkspace() { return <div className="grid gap-6"><SectionHeading title="Lesson progress" detail="Maintain a clear record of what was planned, taught and carried forward."/><Card><CardHeader><CardTitle>September teaching plan</CardTitle><CardDescription>Mathematics · Grade 7 · Blue</CardDescription></CardHeader><CardContent className="grid gap-3">{[["Algebraic expressions","Completed","17 Sep","100"],["Linear equations","In progress","21 Sep","72"],["Ratio and proportion","Planned","28 Sep","10"],["Geometry fundamentals","Planned","05 Oct","0"]].map(([t,s,d,p])=><div key={t} className="grid gap-3 rounded-2xl border p-4 md:grid-cols-[1.3fr_1fr_2fr_auto] md:items-center"><div><p className="text-sm font-semibold">{t}</p><p className="text-xs text-muted-foreground">Target {d}</p></div><StatusBadge value={s}/><Progress value={Number(p)}/><Button variant="ghost" size="sm">Update</Button></div>)}</CardContent></Card></div> }
function UpdatesWorkspace() { return <div className="grid gap-6"><SectionHeading title="Classwork, homework & daily updates" detail="Draft learning notes for approval and parent visibility."/><div className="grid gap-4 xl:grid-cols-[1fr_1.2fr]"><Card><CardHeader><CardTitle>Create update</CardTitle><CardDescription>Share only the information families need.</CardDescription></CardHeader><CardContent className="grid gap-4"><Select defaultValue="7b"><SelectTrigger><SelectValue placeholder="Select class"/></SelectTrigger><SelectContent><SelectGroup><SelectItem value="7b">Grade 7 · Blue</SelectItem><SelectItem value="8b">Grade 8 · Blue</SelectItem></SelectGroup></SelectContent></Select><Select defaultValue="homework"><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem value="homework">Homework</SelectItem><SelectItem value="classwork">Classwork</SelectItem><SelectItem value="notice">Class notice</SelectItem></SelectGroup></SelectContent></Select><Textarea placeholder="Write today’s update…"/><Button onClick={()=>toast.success("Update submitted for approval")}>Submit for approval</Button></CardContent></Card><Card><CardHeader><CardTitle>Recent updates</CardTitle><CardDescription>Draft, approved and published communication</CardDescription></CardHeader><CardContent className="grid gap-3">{[["Practice exercise 4.2, questions 1–8","Grade 7 · Blue","Published"],["Bring geometry set tomorrow","Grade 8 · Blue","Approved"],["Quiz moved to Thursday","Grade 7 · Green","Draft"]].map(([t,c,s])=><div key={t} className="rounded-2xl border p-4"><div className="flex items-start justify-between gap-4"><div><p className="text-sm font-medium">{t}</p><p className="mt-1 text-xs text-muted-foreground">{c} · Mathematics</p></div><StatusBadge value={s}/></div></div>)}</CardContent></Card></div></div> }
function MarksWorkspace({ onAction }: { onAction: (a: ActionKind) => void }) { return <div className="grid gap-6"><SectionHeading title="Exam marks" detail="Enter draft marks, validate bounds and submit the completed sheet."/><Alert><ShieldCheck className="size-4"/><AlertTitle>Controlled submission</AlertTitle><AlertDescription>After submission, marks are locked. Management approval is required to reopen a sheet.</AlertDescription></Alert><Card><CardHeader className="flex-row items-center justify-between"><div><CardTitle>Mid-term 2026 · Mathematics</CardTitle><CardDescription>Grade 7 · Blue · Maximum marks: 100</CardDescription></div><Button onClick={()=>onAction("marks")}><FileCheck2 data-icon="inline-start"/>Open mark sheet</Button></CardHeader><CardContent><div className="grid gap-3 md:grid-cols-3"><div className="rounded-xl bg-muted p-4"><p className="text-xs text-muted-foreground">Entered</p><p className="mt-1 font-heading text-2xl font-semibold">28 / 32</p></div><div className="rounded-xl bg-muted p-4"><p className="text-xs text-muted-foreground">Class average</p><p className="mt-1 font-heading text-2xl font-semibold">74.6%</p></div><div className="rounded-xl bg-muted p-4"><p className="text-xs text-muted-foreground">Status</p><p className="mt-1 font-heading text-2xl font-semibold">Draft</p></div></div></CardContent></Card></div> }

function ParentPortal({ section }: { section: string }) {
  if(section==="Attendance")return <ParentAttendance/>;if(section==="Results & DMC")return <ParentResults/>;if(section==="Fees & receipts")return <ParentFees/>;if(section==="Timetable")return <ParentTimetable/>;if(section==="Updates")return <ParentUpdates/>;
  return <div className="grid gap-6"><div className="flex flex-col gap-4 rounded-3xl border bg-card p-6 md:flex-row md:items-center md:justify-between md:p-8"><div className="flex items-center gap-5"><Avatar className="size-16 border-4 border-background shadow-md"><AvatarFallback className="bg-accent text-lg text-accent-foreground">RA</AvatarFallback></Avatar><div><div className="flex items-center gap-2"><h2 className="font-heading text-2xl font-semibold">Rayan Ahmed</h2><Badge variant="secondary"><BadgeCheck className="size-3"/>Active</Badge></div><p className="mt-1 text-sm text-muted-foreground">Grade 7 · Blue · CLS-24118</p></div></div><Select defaultValue="rayan"><SelectTrigger className="w-full md:w-52"><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem value="rayan">Rayan Ahmed</SelectItem><SelectItem value="maya">Maya Ahmed · Grade 3</SelectItem></SelectGroup></SelectContent></Select></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={UserCheck} label="Attendance" value="95.4%" note="This academic session" tone="accent"/><MetricCard icon={GraduationCap} label="Latest result" value="87.2%" note="Rank 4 of 32"/><MetricCard icon={WalletCards} label="Fee status" value="Paid" note="Through September 2026"/><MetricCard icon={BookOpen} label="Homework" value="03" note="Due this week"/></div><div className="grid gap-4 xl:grid-cols-[1.25fr_1fr]"><Card><CardHeader><CardTitle>Today at school</CardTitle><CardDescription>Monday · 21 September 2026</CardDescription></CardHeader><CardContent className="grid gap-2">{[["08:00","English","Room 14","Present"],["08:45","Mathematics","Room 14","Present"],["09:30","General Science","Lab 02","Present"],["11:15","Computer Studies","Lab 01","Upcoming"]].map(([t,s,r,st])=><div key={t} className="flex items-center gap-4 rounded-xl border p-3"><p className="w-12 text-xs font-semibold">{t}</p><Separator orientation="vertical" className="h-8"/><div className="flex-1"><p className="text-sm font-medium">{s}</p><p className="text-xs text-muted-foreground">{r}</p></div><StatusBadge value={st}/></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Latest updates</CardTitle><CardDescription>Approved by the school</CardDescription></CardHeader><CardContent className="grid gap-4">{[["Homework","Mathematics","Practice exercise 4.2, questions 1–8"],["Notice","School office","Parent-teacher meeting on Saturday"],["Classwork","General Science","Completed chapter 6 lab activity"]].map(([type,sub,text])=><div key={text} className="border-b pb-4 last:border-0 last:pb-0"><div className="flex items-center gap-2"><Badge variant="outline">{type}</Badge><span className="text-xs text-muted-foreground">{sub}</span></div><p className="mt-2 text-sm leading-6">{text}</p></div>)}</CardContent></Card></div></div>
}

function ParentAttendance() { return <div className="grid gap-6"><SectionHeading title="Attendance" detail="Rayan’s daily and monthly attendance record."/><div className="grid gap-4 xl:grid-cols-[1fr_1.4fr]"><Card><CardHeader><CardTitle>September summary</CardTitle><CardDescription>19 instructional days</CardDescription></CardHeader><CardContent><ChartContainer config={attendanceConfig} className="mx-auto h-[250px] max-w-sm"><RechartsPieChart><ChartTooltip content={<ChartTooltipContent nameKey="name"/>}/><Pie data={attendanceData} dataKey="value" nameKey="name" innerRadius={68} outerRadius={96} strokeWidth={4}>{attendanceData.map((entry)=><Cell key={entry.name} fill={entry.fill}/>)}</Pie></RechartsPieChart></ChartContainer><div className="grid grid-cols-3 gap-2 text-center">{[["17","Present"],["1","Absent"],["1","Leave"]].map(([v,l])=><div key={l} className="rounded-xl bg-muted p-3"><p className="font-heading text-xl font-semibold">{v}</p><p className="text-xs text-muted-foreground">{l}</p></div>)}</div></CardContent></Card><Card><CardHeader><CardTitle>Recent attendance</CardTitle><CardDescription>Verified by class teachers</CardDescription></CardHeader><CardContent className="grid grid-cols-5 gap-2 sm:grid-cols-7">{Array.from({length:19},(_,i)=>i+1).map(d=><div key={d} className={`grid aspect-square place-items-center rounded-xl border text-xs font-semibold ${d===9?'border-destructive/20 bg-destructive/10 text-destructive':d===15?'border-accent/30 bg-accent/15 text-accent-foreground':'bg-success/10 text-success'}`}>{d}</div>)}</CardContent></Card></div></div> }
function ParentResults() { return <div className="grid gap-6"><SectionHeading title="Results & DMC" detail="Published examinations, grades and downloadable report cards." action="Download DMC"/><Card className="overflow-hidden"><div className="bg-primary p-6 text-primary-foreground"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><Badge className="bg-primary-foreground/10 text-primary-foreground">Published</Badge><h2 className="mt-4 font-heading text-2xl font-semibold">Monthly Assessment · August 2026</h2><p className="mt-1 text-sm text-primary-foreground/60">Grade 7 · Blue</p></div><div className="flex gap-6"><div><p className="text-xs text-primary-foreground/55">Overall</p><p className="font-heading text-3xl font-semibold">87.2%</p></div><div><p className="text-xs text-primary-foreground/55">Rank</p><p className="font-heading text-3xl font-semibold">04</p></div></div></div></div><CardContent className="pt-6"><Table><TableHeader><TableRow><TableHead>Subject</TableHead><TableHead>Marks</TableHead><TableHead>Grade</TableHead><TableHead>Class average</TableHead></TableRow></TableHeader><TableBody>{[["English","86 / 100","A","78%"],["Mathematics","94 / 100","A+","76%"],["General Science","89 / 100","A","74%"],["Urdu","81 / 100","A","72%"],["Computer Studies","92 / 100","A+","82%"]].map(r=><TableRow key={r[0]}><TableCell className="font-medium">{r[0]}</TableCell><TableCell>{r[1]}</TableCell><TableCell><Badge variant="secondary">{r[2]}</Badge></TableCell><TableCell>{r[3]}</TableCell></TableRow>)}</TableBody></Table></CardContent></Card></div> }
function ParentFees() { return <div className="grid gap-6"><SectionHeading title="Fees & receipts" detail="A read-only view of dues, paid periods and verified receipts." action="Download statement"/><Alert className="border-success/20 bg-success/[0.04]"><BadgeCheck className="size-4 text-success"/><AlertTitle>All clear</AlertTitle><AlertDescription>Fees are paid through September 2026. Next tuition fee is due 10 October.</AlertDescription></Alert><div className="grid gap-4 lg:grid-cols-3"><MetricCard icon={WalletCards} label="Current outstanding" value="₨ 0" note="No overdue balance" tone="accent"/><MetricCard icon={ReceiptText} label="Paid this session" value="₨ 76,500" note="9 verified receipts"/><MetricCard icon={BriefcaseBusiness} label="Advance balance" value="₨ 8,500" note="Available for October"/></div><Card><CardHeader><CardTitle>Receipt history</CardTitle><CardDescription>Verified school receipts only</CardDescription></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Receipt</TableHead><TableHead>Period</TableHead><TableHead>Paid on</TableHead><TableHead>Amount</TableHead><TableHead/></TableRow></TableHeader><TableBody>{[["RCPT-0926-482","September 2026","05 Sep 2026","₨ 8,500"],["RCPT-0826-377","August 2026","04 Aug 2026","₨ 8,500"],["RCPT-0726-294","July 2026","07 Jul 2026","₨ 8,500"]].map(r=><TableRow key={r[0]}><TableCell className="font-mono text-xs">{r[0]}</TableCell><TableCell>{r[1]}</TableCell><TableCell>{r[2]}</TableCell><TableCell>{r[3]}</TableCell><TableCell><Button variant="ghost" size="icon-sm"><Download/></Button></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></div> }
function ParentTimetable() { return <div className="grid gap-6"><SectionHeading title="Weekly timetable" detail="Rayan Ahmed · Grade 7 · Blue · Session 2026–27"/><Card><CardContent className="overflow-x-auto p-5"><div className="grid min-w-[760px] grid-cols-[80px_repeat(5,1fr)] gap-2 text-xs"><div/>{["Monday","Tuesday","Wednesday","Thursday","Friday"].map(d=><div key={d} className="pb-3 text-center font-semibold">{d}</div>)}{["08:00","08:45","09:30","11:15","12:00"].flatMap((time,row)=>[<div key={time} className="pt-4 text-muted-foreground">{time}</div>,...["English","Mathematics","Science","Computer","Urdu"].map((s,col)=><div key={`${row}-${col}`} className="min-h-20 rounded-xl border bg-muted/30 p-3"><p className="font-semibold">{[s,"Mathematics","General Science","Social Studies"][(row+col)%4]}</p><p className="mt-2 text-muted-foreground">Room {12+((row+col)%7)}</p></div>)])}</div></CardContent></Card></div> }
function ParentUpdates() { return <div className="grid gap-6"><SectionHeading title="School updates" detail="Approved homework, classwork and notices for linked children."/><div className="grid gap-4 md:grid-cols-2">{[["Homework","Mathematics","Practice exercise 4.2, questions 1–8","Due 23 Sep"],["Notice","School office","Parent-teacher meeting is scheduled this Saturday.","19 Sep"],["Classwork","General Science","Completed chapter 6 laboratory activity.","Today"],["Homework","English","Prepare a short talk on environmental responsibility.","Due 25 Sep"]].map(([type,subject,text,date])=><Card key={text}><CardHeader><div className="flex items-center justify-between"><Badge variant="secondary">{type}</Badge><span className="text-xs text-muted-foreground">{date}</span></div><CardTitle className="mt-4 text-base">{subject}</CardTitle><CardDescription className="text-sm leading-6 text-foreground/75">{text}</CardDescription></CardHeader><CardFooter className="text-xs text-muted-foreground"><BadgeCheck className="mr-2 size-4 text-success"/>Approved and visible to parents</CardFooter></Card>)}</div></div> }

function ActionDialog({ kind, onClose }: { kind: ActionKind; onClose: () => void }) {
  const title=kind==="admission"?"Create new admission":kind==="payment"?"Record fee payment":kind==="sync"?"Synchronise offline fees":kind==="attendance"?"Mark class attendance":"Review mark sheet";const submitLabel=kind==="sync"?"Validate & import":kind==="marks"?"Save draft":kind==="attendance"?"Save attendance":"Save record";const handleSubmit=()=>{toast.success(kind==="sync"?"84 rows imported · 2 skipped · 1 failed":`${title} saved successfully`);onClose()}
  return <Dialog open={kind!==null} onOpenChange={(value)=>!value&&onClose()}><DialogContent className="sm:max-w-xl"><DialogHeader><DialogTitle>{title}</DialogTitle><DialogDescription>{kind==="sync"?"Upload the controlled template. Every row is validated before entering the fee ledger.":"This interactive prototype demonstrates the SRS workflow and its validation points."}</DialogDescription></DialogHeader>{kind==="admission"&&<div className="grid gap-4 py-2 sm:grid-cols-2"><div className="grid gap-2"><label className="text-xs font-medium">Student name</label><Input placeholder="Full legal name"/></div><div className="grid gap-2"><label className="text-xs font-medium">Date of birth</label><Input type="date"/></div><div className="grid gap-2"><label className="text-xs font-medium">Applying for</label><Select defaultValue="g7"><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem value="g7">Grade 7</SelectItem><SelectItem value="g8">Grade 8</SelectItem></SelectGroup></SelectContent></Select></div><div className="grid gap-2"><label className="text-xs font-medium">Guardian name</label><Input placeholder="Primary guardian"/></div><div className="grid gap-2 sm:col-span-2"><label className="text-xs font-medium">Admission notes</label><Textarea placeholder="Interview, documents or special notes…"/></div></div>}{kind==="payment"&&<div className="grid gap-4 py-2 sm:grid-cols-2"><div className="grid gap-2 sm:col-span-2"><label className="text-xs font-medium">Student ID or name</label><Input placeholder="Search enrolled student"/></div><div className="grid gap-2"><label className="text-xs font-medium">Fee period</label><Select defaultValue="sep"><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem value="sep">September 2026</SelectItem><SelectItem value="oct">October 2026</SelectItem></SelectGroup></SelectContent></Select></div><div className="grid gap-2"><label className="text-xs font-medium">Amount</label><Input defaultValue="8500"/></div><div className="grid gap-2"><label className="text-xs font-medium">Payment method</label><Select defaultValue="cash"><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem value="cash">Cash</SelectItem><SelectItem value="bank">Bank transfer</SelectItem></SelectGroup></SelectContent></Select></div><div className="grid gap-2"><label className="text-xs font-medium">Receipt reference</label><Input placeholder="Must be unique"/></div></div>}{kind==="sync"&&<div className="py-2"><label className="flex min-h-44 cursor-pointer flex-col items-center justify-center rounded-2xl border border-dashed bg-muted/30 p-8 text-center"><span className="grid size-12 place-items-center rounded-xl bg-background shadow-sm"><CloudUpload className="size-5"/></span><span className="mt-4 text-sm font-semibold">Drop controlled fee workbook here</span><span className="mt-1 text-xs text-muted-foreground">.xlsx · unique receipt references required</span><Input type="file" accept=".xlsx" className="sr-only"/></label><Alert className="mt-4"><ShieldCheck className="size-4"/><AlertTitle>Duplicate protection is on</AlertTitle><AlertDescription>Existing receipt references will be skipped and included in the error report.</AlertDescription></Alert></div>}{kind==="attendance"&&<div className="grid gap-2 py-2">{["Ayaan Malik","Zoya Khan","Hamza Noor","Maira Ali","Rayan Ahmed"].map((name,i)=><label key={name} className="flex items-center gap-3 rounded-xl border p-3"><Checkbox defaultChecked={i!==2}/><span className="flex-1 text-sm font-medium">{name}</span><Badge variant={i===2?"outline":"secondary"}>{i===2?"Absent":"Present"}</Badge></label>)}<p className="mt-2 text-xs text-muted-foreground">Preview shows 5 of 29 enrolled students.</p></div>}{kind==="marks"&&<div className="grid gap-2 py-2">{[["Rayan Ahmed","94"],["Zoya Khan","88"],["Hamza Noor","76"],["Maira Ali","91"]].map(([name,score])=><div key={name} className="grid grid-cols-[1fr_88px_70px] items-center gap-3 rounded-xl border p-3"><span className="text-sm font-medium">{name}</span><Input defaultValue={score} type="number" min="0" max="100"/><span className="text-xs text-muted-foreground">/ 100</span></div>)}</div>}<DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button onClick={handleSubmit}>{submitLabel}</Button></DialogFooter></DialogContent></Dialog>
}

function Portal() {
  const [role, setRole] = useState<Role>("management")
  const [loggedIn, setLoggedIn] = useState(false)
  const [section, setSection] = useState(navigation.management[0].label)
  const [action, setAction] = useState<ActionKind>(null)
  const [mobileNavOpen, setMobileNavOpen] = useState(false)
  const subtitle =
    role === "management"
      ? "A live view of people, learning and school operations."
      : role === "teacher"
        ? "Your assigned work for a focused, well-run day."
        : "Everything important about Rayan, in one calm place."
  const changeRole = (newRole: Role) => {
    setRole(newRole)
    setSection(navigation[newRole][0].label)
    setMobileNavOpen(false)
  }
  const navigateSection = (label: string) => {
    setSection(label)
    setMobileNavOpen(false)
  }
  const logout = () => {
    setLoggedIn(false)
    setMobileNavOpen(false)
  }
  const content = useMemo(() => {
    if (role === "teacher") return <TeacherPortal section={section} onAction={setAction} />
    if (role === "parent") return <ParentPortal section={section} />
    if (section === "Academic setup") return <AcademicSetup />
    if (section === "Admissions") return <Admissions onAction={setAction} />
    if (section === "Examinations") return <Examinations onAction={setAction} />
    if (section === "Fees & sync") return <Fees onAction={setAction} />
    if (section === "Finance") return <Finance />
    if (section === "Reports & audit") return <Reports />
    if (section === "SRS delivery map") return <DeliveryMap />
    return <ManagementDashboard onAction={setAction} />
  }, [role, section])
  if (!loggedIn) {
    return (
      <LoginScreen
        onEnter={(r) => {
          changeRole(r)
          setLoggedIn(true)
        }}
      />
    )
  }
  return (
    <div className="min-h-svh bg-muted/25">
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-64 border-r bg-sidebar md:block">
        <SidebarNav role={role} active={section} onNavigate={navigateSection} onRole={changeRole} onLogout={logout} />
      </aside>
      <div className="md:pl-64">
        <div className="flex items-center gap-3 border-b bg-background px-4 py-3 md:hidden">
          <Sheet open={mobileNavOpen} onOpenChange={setMobileNavOpen}>
            <SheetTrigger asChild>
              <Button variant="outline" size="icon">
                <Menu />
              </Button>
            </SheetTrigger>
            <SheetContent side="left" className="w-72 p-0">
              <SheetHeader className="sr-only">
                <SheetTitle>Portal navigation</SheetTitle>
                <SheetDescription>Choose a section of the school portal.</SheetDescription>
              </SheetHeader>
              <SidebarNav role={role} active={section} onNavigate={navigateSection} onRole={changeRole} onLogout={logout} />
            </SheetContent>
          </Sheet>
          <Logo />
        </div>
        <PageHeader role={role} title={section} subtitle={subtitle} onAction={setAction} />
        <main className="mx-auto w-full max-w-[1500px] p-4 sm:p-6 md:p-8">{content}</main>
      </div>
      <ActionDialog kind={action} onClose={() => setAction(null)} />
    </div>
  )
}

export default function App(){return <Portal/>}
